#include <bits/stdc++.h>
using namespace std;
int main(int argc,char**argv){ios::sync_with_stdio(false);cin.tie(nullptr); string nm; int n,theta;cin>>nm>>n>>theta;vector<vector<int>> adj(n); for(int i=0;i<n;i++){int d;cin>>d;adj[i].resize(d);for(int &v:adj[i])cin>>v;} int powers[21]={1};for(int i=1;i<=n;i++)powers[i]=powers[i-1]*3; int N=powers[n]; vector<int>next(N); for(int st=0;st<N;st++){int z=st,states[20];for(int i=0;i<n;i++){states[i]=z%3;z/=3;}int nxt=0;for(int i=0;i<n;i++){int c=0;for(int v:adj[i])c+=(states[v]==1);int r=(states[i]==1)?2:(states[i]==2)?0:(c>=theta)?1:0;nxt+=r*powers[i];}next[st]=nxt;}
 vector<int>status(N,-1),ent(N,0),period(N,0),root(N,-1),pos(N,-1);vector<int> stack;stack.reserve(1000);map<int,long long> cyclecounts;int attractors=0;vector<int> bases;vector<int> reps;vector<int> lens;map<pair<int,int>,long long> hp;map<int,int> maxentbyperiod;int globalmax=0;int witness=0;for(int u=0;u<N;u++){if(status[u]!=-1)continue;stack.clear();int v=u;while(status[v]==-1){status[v]=-2;pos[v]=stack.size();stack.push_back(v);v=next[v];}if(status[v]==-2){int cstart=pos[v],len=stack.size()-cstart,r=attractors++;cyclecounts[len]++;bases.push_back(len);reps.push_back(v);lens.push_back(len);for(int j=cstart;j<(int)stack.size();j++){int t=stack[j];status[t]=1;ent[t]=0;period[t]=len;root[t]=r;}stack.resize(cstart);}for(int j=(int)stack.size()-1;j>=0;j--){int a=stack[j],b=next[a];status[a]=1;ent[a]=ent[b]+1;period[a]=period[b];root[a]=root[b];bases[root[a]]++;} }
 for(int i=0;i<N;i++){hp[{ent[i],period[i]}]++;if(ent[i]>globalmax){globalmax=ent[i];witness=i;}maxentbyperiod[period[i]]=max(maxentbyperiod[period[i]],ent[i]);}
 map<int,map<int,int>> sizeb;for(int i=0;i<attractors;i++)sizeb[(int)0][bases[i]]++;
 cout<<"GRAPH "<<nm<<" n="<<n<<" threshold="<<theta<<" states="<<N<<"\n";cout<<"ATTRACTORS ";for(auto &x:cyclecounts)cout<<x.first<<":"<<x.second<<" ";cout<<"\nMAXENT "<<globalmax<<" witness="<<witness<<"\n";cout<<"JOINT ";for(auto &x:hp)cout<<"("<<x.first.first<<","<<x.first.second<<")="<<x.second<<" ";cout<<"\nBASINS ";for(auto&x:sizeb[0])cout<<x.first<<":"<<x.second<<" ";cout<<"\n";
 for(int i=0;i<attractors;i++)if(lens[i]==13){int st=reps[i];string tr;for(int j=0;j<n;j++){tr+=char('0'+st%3);st/=3;}cout<<"PERIOD13 "<<i<<" rep="<<reps[i]<<" colors="<<tr<<" basin="<<bases[i]<<"\n";}
 map<pair<int,int>,map<int,int>> bh;for(int i=0;i<attractors;i++)bh[{lens[i],0}][bases[i]]++;for(auto &a:bh){cout<<"BASINPERIOD "<<a.first.first<<" ";for(auto &b:a.second)cout<<b.first<<":"<<b.second<<" ";cout<<"\n";}
}
